// Extract request inputs
const body = $json.body || $json || {};
const topic = String(body.topic || body.studyText || body.title || 'General Knowledge').trim();
const score = typeof body.score === 'number' ? Math.max(0, Math.min(100, body.score)) : (typeof body.scorePercentage === 'number' ? Math.max(0, Math.min(100, body.scorePercentage)) : 50);
const count = Math.max(1, Math.min(50, Number(body.numberOfQuestions || body.count || body.questionCount) || 5));

// Format previous questions to avoid repetition
let previousQuestions = [];
if (Array.isArray(body.previousQuestions)) {
  previousQuestions = body.previousQuestions.map((q) => typeof q === 'string' ? q : (q.question || q.questionText || '')).filter(Boolean);
} else if (typeof body.previousQuestions === 'string' && body.previousQuestions.trim()) {
  previousQuestions = [body.previousQuestions.trim()];
}

// Format weak topics
let weakTopics = [];
if (Array.isArray(body.weakTopics)) {
  weakTopics = body.weakTopics.map(String).filter(Boolean);
} else if (typeof body.weakTopics === 'string' && body.weakTopics.trim()) {
  weakTopics = body.weakTopics.split(',').map((s) => s.trim()).filter(Boolean);
}

// DIFFICULTY RULES:
// 0-30%: 70% Easy, 30% Medium, 0% Hard
// 31-50%: 50% Easy, 40% Medium, 10% Hard
// 51-70%: 30% Easy, 50% Medium, 20% Hard
// 71-85%: 20% Easy, 50% Medium, 30% Hard
// 86-100%: 10% Easy, 40% Medium, 50% Hard
let easyPct = 0.30, medPct = 0.50, hardPct = 0.20;
if (score <= 30) {
  easyPct = 0.70; medPct = 0.30; hardPct = 0.00;
} else if (score <= 50) {
  easyPct = 0.50; medPct = 0.40; hardPct = 0.10;
} else if (score <= 70) {
  easyPct = 0.30; medPct = 0.50; hardPct = 0.20;
} else if (score <= 85) {
  easyPct = 0.20; medPct = 0.50; hardPct = 0.30;
} else {
  easyPct = 0.10; medPct = 0.40; hardPct = 0.50;
}

// Convert percentages into exact integer number of questions
let easyCount = Math.round(count * easyPct);
let hardCount = Math.round(count * hardPct);

// Guarantee 0% Hard in 0-30% tier
if (score <= 30) {
  hardCount = 0;
}

let medCount = count - (easyCount + hardCount);

// Boundary correction if rounding causes overflow or underflow
if (medCount < 0) {
  easyCount += medCount;
  medCount = 0;
}

const totalAllocated = easyCount + medCount + hardCount;
if (totalAllocated !== count) {
  medCount += (count - totalAllocated);
}

const distribution = {
  easy: Math.max(0, easyCount),
  medium: Math.max(0, medCount),
  hard: Math.max(0, hardCount)
};

return [{
  json: {
    topic,
    score,
    count,
    distribution,
    previousQuestions,
    weakTopics,
    rawStudyText: body.studyText || topic
  }
}];

