const prev = $('Compute Adaptive Distribution').first().json;
const content = $json.choices?.[0]?.message?.content || '';
let cleaned = content.trim();
if (cleaned.startsWith('```json')) {
  cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
} else if (cleaned.startsWith('```')) {
  cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
}

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    parsed = JSON.parse(match[0]);
  } else {
    throw new Error('Could not parse adaptive quiz JSON from model response');
  }
}

const rawQuestions = Array.isArray(parsed?.questions) ? parsed.questions : (Array.isArray(parsed) ? parsed : []);

// Format questions ensuring both requested schema and Peer Club backward compatibility
const formattedQuestions = rawQuestions.map((q, idx) => {
  const options = Array.isArray(q.options) && q.options.length >= 2 ? q.options : ['Option A', 'Option B', 'Option C', 'Option D'];
  const correctAnswer = q.correct_answer || q.correctAnswer || (typeof q.correctIndex === 'number' ? options[q.correctIndex] : options[0]);
  let correctIndex = options.findIndex((opt) => String(opt).trim().toLowerCase() === String(correctAnswer).trim().toLowerCase());
  if (correctIndex === -1) {
    correctIndex = typeof q.correctIndex === 'number' ? q.correctIndex : 0;
  }

  return {
    id: q.id || `q${idx + 1}`,
    difficulty: (q.difficulty || 'medium').toLowerCase(),
    question: q.question || q.questionText || `Question ${idx + 1}`,
    questionText: q.question || q.questionText || `Question ${idx + 1}`,
    questionType: 'mcq',
    options,
    correct_answer: correctAnswer,
    correctAnswer,
    correctIndex,
    explanation: q.explanation || 'Verified concept explanation.'
  };
});

return [{
  json: {
    success: true,
    topic: parsed?.topic || prev.topic,
    score: typeof parsed?.score === 'number' ? parsed.score : prev.score,
    difficulty_distribution: parsed?.difficulty_distribution || prev.distribution,
    questions: formattedQuestions
  }
}];
